SourceCode.Declaration:
/// <summary>
/// Authenticated custom-service facade for immediate and durable interpreted X++.
/// The interpreter is already loaded in AOS; this operation never invokes xppc,
/// package deployment, database synchronization, or SysTest.
/// </summary>
public final class MXTXppInterpreterService
{
}

Method.Source:
/// <summary>
/// Parses, compiles to interpreter bytecode, and executes source in the current
/// AOS request. Database work is always aborted before the response is returned.
/// </summary>
[SysEntryPointAttribute(true)]
public MXTXppInterpreterExecutionResponse execute(MXTXppInterpreterExecutionRequest _request)
{
    return MXTXppInterpreterExecutor::executeFast(_request);
}

/// <summary>Creates an immutable staged module version and optionally activates it.</summary>
[SysEntryPointAttribute(true)]
public MXTXppInterpreterModuleResponse deployModule(MXTXppInterpreterModuleRequest _request)
{
    return MXTXppInterpreterModuleRegistry::deploy(_request);
}

/// <summary>Validates, compiles, caches, and atomically activates a staged version.</summary>
[SysEntryPointAttribute(true)]
public MXTXppInterpreterModuleResponse activateModule(MXTXppInterpreterModuleRequest _request)
{
    return MXTXppInterpreterModuleRegistry::activate(_request);
}

/// <summary>Atomically activates a prior immutable version.</summary>
[SysEntryPointAttribute(true)]
public MXTXppInterpreterModuleResponse rollbackModule(MXTXppInterpreterModuleRequest _request)
{
    return MXTXppInterpreterModuleRegistry::rollback(_request);
}

/// <summary>Executes an active or explicitly selected module version with database rollback.</summary>
[SysEntryPointAttribute(true)]
public MXTXppInterpreterExecutionResponse executeModule(MXTXppInterpreterModuleRequest _request)
{
    return MXTXppInterpreterModuleRegistry::execute(_request);
}

/// <summary>Returns source and version history for a module.</summary>
[SysEntryPointAttribute(true)]
public MXTXppInterpreterModuleResponse getModule(MXTXppInterpreterModuleRequest _request)
{
    return MXTXppInterpreterModuleRegistry::get(_request);
}

/// <summary>Lists all durable interpreted modules and their active/latest versions.</summary>
[SysEntryPointAttribute(true)]
public MXTXppInterpreterModuleListResponse listModules()
{
    return MXTXppInterpreterModuleRegistry::list();
}
